import numpy as np
from scipy.optimize import minimize
import random

def f(params):
    x, y, z = params
    if x <= 0 or y <= 0 or z <= 0:
        return 1e9
    return (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1) / (x*y + y*z + z*x)

min_val = 1e9
for _ in range(100):
    start = (random.uniform(0.1, 10) for _ in range(3))
    res = minimize(f, [s for s in start], bounds=((1e-6, None), (1e-6, None), (1e-6, None)))
    if res.success:
        min_val = min(min_val, res.fun)

print(f"Minimum value after 100 random starts: {min_val}")
